const items = $input.all();
const system = 'Ты — модуль извлечения памяти персонального фитнес-бота. По текущей выжимке и новым сообщениям обнови память клиента. Ответь СТРОГО одним JSON-объектом без markdown и пояснений. Ключи: summary (строка — обновлённая краткая выжимка: цели, прогресс, что сработало и что нет, договорённости, важные детали; учти старое и новое, 2-4 абзаца); measurements (массив {metric,value,unit,measured_on} — числовые факты клиента, measured_on YYYY-MM-DD или пусто); allergens (массив {substance,severity: allergy|intolerance}); conditions (массив {name}); injuries (массив {area,status: active|rehab|resolved}); medications (массив {name,dose}); preferences (массив {item,stance: like|dislike}). Извлекай ТОЛЬКО реально сообщённое клиентом, пустые массивы если ничего, ничего не выдумывай.';
const PRG_RULE = " ПРОГРАММА ТРЕНИРОВОК у клиента сохранена отдельно и главнее любой сводки: состав тренировочных дней, списки упражнений, сплиты, кардио и раскладки тренировок, которые выдавал бот, в сводку НЕ пиши. Если клиент изменил программу — одна строка «программу тренировок изменили: что именно».";
const NOPRG_RULE = " Сохранённой программы тренировок у клиента нет: если клиент ЯВНО согласовал программу (состав дней), зафиксируй кратко только ПОСЛЕДНЮЮ согласованную версию и прямо напиши, что прежние версии отменены. Раскладку, которую бот выдал сам без подтверждения клиента, как программу или договорённость не записывай.";
const out = [];
for (let i = 0; i < items.length; i++) {
  const d = items[i].json;
  const transcript = String(d.transcript || "").trim();
  if (!transcript) continue;
  const cur = String(d.current_summary || "").trim() || "(выжимки пока нет)";
  const user = "ТЕКУЩАЯ ВЫЖИМКА О КЛИЕНТЕ:\n" + cur + "\n\nНОВЫЕ СООБЩЕНИЯ:\n" + transcript;
  const body = JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: 2000, system: system + (d.has_program === true || d.has_program === 't' || d.has_program === 'true' ? PRG_RULE : NOPRG_RULE), messages: [{ role: "user", content: user }] });
  out.push({ json: { bot_id: d.bot_id, user_id: d.user_id, max_id: d.max_id, body: body }, pairedItem: { item: i } });
}
return out;

const out = [];
const inp = $input.all();
const prompts = $("Промпт").all();
for (let i = 0; i < inp.length; i++) {
  const r = inp[i].json;
  const p = prompts[i].json;
  let text = "";
  try { text = r.content[0].text; } catch (e) { text = ""; }
  text = String(text).replace(/^```json\s*/i, "").replace(/^```\s*/, "").replace(/```\s*$/, "").trim();
  const si = text.indexOf("{"); const ei = text.lastIndexOf("}");
  let payload = "{}";
  if (si >= 0 && ei > si) payload = text.slice(si, ei + 1);
  try { JSON.parse(payload); } catch (e) { payload = "{}"; }
  out.push({ json: { bot_id: p.bot_id, user_id: p.user_id, max_id: p.max_id, payload: payload }, pairedItem: { item: i } });
}
return out;
